const form=root.querySelector('form'),message=root.querySelector('.cement-message');
if(kind==='granel'){
 const contractField=form.elements.supplierOrder;
 const getActiveContract=()=>{
  let stored;
  try{stored=JSON.parse(localStorage.getItem('colafix-bulk-prices-v1')||'{}')}catch{return null}
  const date=form.elements.scheduledDate.value||new Date().toLocaleDateString('sv-SE');
  if(!Array.isArray(stored?.contracts))return null;
  // O contrato mais recente continua aplicável até outro contrato mais novo
  // entrar em vigor; o vencimento cadastrado não bloqueia agendamentos.
  const available=stored.contracts.filter(x=>x&&x.number&&(!x.start||x.start<=date));
  available.sort((a,b)=>String(b.start||'').localeCompare(String(a.start||''))||String(b.end||'').localeCompare(String(a.end||'')));
  return available[0]||null;
 };
 const syncContract=()=>{
  const supplier=form.elements.supplier.value,previous=form.dataset.contractSupplier||supplier,changed=previous!==supplier;
  form.dataset.contractSupplier=supplier;
  if(supplier!=='Votorantim'){
   if(changed||contractField.dataset.autoContract==='1'){contractField.value='';delete contractField.dataset.autoContract}
   contractField.title='Intercement: sem contrato fixo. Informe referencia somente se necessario para esta carga.';
   return;
  }
  const contract=getActiveContract();
  if(contract){
   if(changed||!contractField.value.trim()||contractField.dataset.autoContract==='1'){contractField.value=String(contract.number);contractField.dataset.autoContract='1'}
   contractField.title='Contrato Votorantim mais recente cadastrado: '+contract.start+' ate '+contract.end;
  }else{
   if(changed||contractField.dataset.autoContract==='1')contractField.value='';
   delete contractField.dataset.autoContract;
  }
 };
 form.elements.supplier.addEventListener('change',syncContract);
 form.elements.scheduledDate.addEventListener('change',syncContract);
 form.elements.company.addEventListener('change',syncContract);
 contractField.addEventListener('input',()=>{delete contractField.dataset.autoContract});
 root._syncVotorantimContract=syncContract;
 syncContract();
}
