function whatsappText(r,kind){const lines=['*AGENDAMENTO DE CARGA*','Status: *'+(r.status||'—')+'*','Data: '+day(r.scheduledDate),'Venc. boleto: '+day(r.dueDate||dueFromScheduled(r.scheduledDate)),'Entrega: '+(r.company||'—')];if(kind==='granel'){lines.push('Fornecedor: '+(r.supplier||'—'),'Pedido sistema: '+(r.systemOrder||'—'),'Pedido/contrato: '+(r.supplierOrder||'—'),'Quantidade: '+(r.orderQuantity||'—'),'Cimento: '+(r.cementDescription||'—'),'Transportador: '+(r.carrier||'—'));}else{bagItems(r).forEach((x,i)=>lines.push('Produto '+(i+1)+': '+(x.product||'—')+' - '+(x.quantity||'—')+' SC - OC: '+(x.purchaseOrder||r.purchaseOrder||'—')));lines.push('Total: '+bagTotal(r)+' SC','Cidade: '+(r.deliveryCity||'—'),'Freteiro: '+(r.carrier||'—'),'OC Freteiro: '+(r.freightOrder||'—'),'Valor frete: '+(r.freightValue||'—'));}if(r.invoice)lines.push('NF: '+r.invoice);if(r.notes)lines.push('Observações: '+r.notes);return lines.join('\n');}
